<?PHPrequire_once $_SERVER['DOCUMENT_ROOT']."/Admin/include/security.php";require_once $_SERVER['DOCUMENT_ROOT']."/Admin/include/set_work_category.php";require_once $_SERVER['DOCUMENT_ROOT']."/Admin/include/admintop.php";require_once $_SERVER['DOCUMENT_ROOT']."/Admin/include/classfactory.php";if ( !isset ( $GLOBALS["common"] ) ) {	$common = & ClassFactory::getInstance ( "DS_Common" );	$common->connect();}class GameModifiers {	var $errormsg;	var $userManager;	function GameModifiers ($userManager)	{		$this->userManager = $userManager;		$this->getRequest ( $_POST );	}	function getRequest ( $request ) {		if ( isset( $request["submit"] ) ){  			$this->updateModifiers( $request['modif']);			$this->showFirstMenu ( $this->errormsg );		}else{			if ( @ereg ( $_SERVER["PHP_SELF"], $_SERVER["HTTP_REFERER"] ) ) {				$this->showFirstMenu ( "<div class='FormText'>".local( 'DS_ACTION_SUCCEED ' )."</div>" );			} else {				$this->showFirstMenu ( "<div class=\"FormText\"></div>" );			}		}		return true;	}	function showFirstMenu()	{		global $common;		$common->setDbId(0);		//Вы описание модифаеров и их тип		$sql =			"SELECT							mtpl.descforuser, 							mtpl.indesc,                        	coalesce(mt.typename, '_OUT_OF_GROUP') as typename,                        	modifiername						FROM							ds_gamemodifiertemplate mtpl						LEFT JOIN ds_gamemodifiertype mt ON (mtpl.id_modifiertype = mt.id_modifiertype)					";		$modifierDesc = $common->getResultArray ( "", $sql, "", "", "" );		if (!empty($common->errormsg))		{			echo "<br><font color='red'>Can't get desc of modifiers: $common->errormsg</font><br>";			return;		}		foreach ($modifierDesc as $modifierKey => $modifierData)		{        	$resArr[$modifierData['typename']][$modifierData['modifiername']]['descforuser'] = $modifierData['descforuser'];		    $resArr[$modifierData['typename']][$modifierData['modifiername']]['indesc'] = $modifierData['indesc'];		}                /*echo "<pre>";                print_r($resArr);                exit;    */		echo '<script  type=text/javascript>				function display(elem) {				                if (document.getElementById(elem).style.display != "") {				                    document.getElementById(elem).style.display = "";				                }				                else {				                    document.getElementById(elem).style.display = "none";				                }				                return false;				            }				window.onload = function() {';		foreach ($resArr as $typename => $typedata)		{			echo ' document.getElementById("'.$typename.'").style.display = "none"; ';		}		echo		'}				</script>';		echo "					<form action='".$_SERVER["PHP_SELF"]."' method='POST'>";		echo "<table cellSpacing='5' cellPadding='0' border='0' width='100%'>";		//Сортируем по группе модифаеров		ksort($resArr);		foreach ($resArr as $typename => $typedata)		{			//Сортируем по названию модифаеров			ksort($typedata);			echo '<tr>					<td bgcolor="444E6C" class="FormText">					<a class="city" href="#" onclick="return display(\''.$typename.'\')"><b>'.$typename.'</b></a></td>				</tr>				';			echo '						<tr id="'.$typename.'"><td>';			echo '<table border=0 width="100%">';            ksort($typedata);			if (count($typedata) > 0)			{				foreach ($typedata as $modifierName => $modifierData)				{                       if($modifierData['indesc'] == 't')						{							$checked = 'checked';						} else {							$checked = '';						}					echo '						<tr>';					echo "							<td bgcolor=\"444E6C\" class=\"FormText\" width='400'>".$modifierName."</td>							<td bgcolor=\"444E6C\"><input type='checkbox' name='modif[".$modifierName."][indesc]' value='t' ".$checked."></td>							<td bgcolor=\"444E6C\"><input type='text' size='100' name='modif[".$modifierName."][desc]' value='".$modifierData['descforuser']."'></td>						</tr>						";					//Кладем модифаер в сессию					$_SESSION['ADMIN_GAME_MODIFAER_DESC'][$modifierName]['desc'] = $modifierData['descforuser'];				    $_SESSION['ADMIN_GAME_MODIFAER_DESC'][$modifierName]['indesc'] = $modifierData['indesc'];				}			}			echo '</table>';			echo '</td></tr>			<tr><td>&nbsp;</td></tr>';		}		echo "		<tr>			<td><input type='submit' class=Submit value='". local( 'DS_ACTION_SUBMIT' )."' name='submit'></td>			<td></td>		</tr>		</table></form>";		return true;	}	function updateModifiers ($modif='') {			/*echo "<pre>";		print_r( $modif) ;       	exit;     */       	/*echo "<pre>";		print_r( $_SESSION['ADMIN_GAME_MODIFAER_DESC']) ;       	exit;     */		global $common;		$common->setDbId(0);		if ($modif == "") {			$this->errormsg = "missing argument";			return false;		}		$common->executeQuery ( 'begin' );		$changetAttributes = array();		foreach($modif as $modifName => $modifData)		{			if($_SESSION['ADMIN_GAME_MODIFAER_DESC'][$modifName]['desc'] != stripcslashes($modifData['desc']))			{                  $sql = "					UPDATE						ds_gamemodifiertemplate					SET						descforuser = '".pg_escape_string(stripcslashes($modifData['desc']))."'					WHERE						modifiername ='".$modifName."'";					$res2 = $common->executeQuery($sql);					assert(empty($common->errormsg));				/*				$changetAttributes[$modifname[$i]] = array				(					'OLD_VALUE' => $_SESSION['ADMIN_GAME_MODIFAERS'][$modifname[$i]],					'NEW_VALUES' => $modif[$i]				);     */			}			if($_SESSION['ADMIN_GAME_MODIFAER_DESC'][$modifName]['indesc'] == 't' && !key_exists('indesc', $modifData))			{                $sql = "					UPDATE						ds_gamemodifiertemplate					SET						indesc = 'f'					WHERE						modifiername ='".$modifName."'";					$res2 = $common->executeQuery($sql);					assert(empty($common->errormsg));			}			if($_SESSION['ADMIN_GAME_MODIFAER_DESC'][$modifName]['indesc'] == 'f' && key_exists('indesc', $modifData))			{                  $sql = "					UPDATE						ds_gamemodifiertemplate					SET						indesc = 't'					WHERE						modifiername ='".$modifName."'";					$res2 = $common->executeQuery($sql);					assert(empty($common->errormsg));			}		}		$common->executeQuery('commit');		assert(empty($common->errormsg));		//Сбрасывем кеши     !!!!!!!!!!		//$cache = DS_Cache::Singleton();		//$cache->delete($dbId."_GAME_MODIFAERS_".$wid);		return true;	}}$nw = new GameModifiers($UserManager);require_once $_SERVER['DOCUMENT_ROOT']."/Admin/include/adminbottom.php";?>